components/papathemes/sale-countdown/dis:
{{!--
Display sale countdown for product based on variables `_saleCountdownDate`, `_saleCountdownLabel`,
`_saleCountdownEndLabel`, `_salePercent`.
Input:
- theme_settings: object - theme settings.
--}}

{{#if (getVar '_saleCountdownDate')}}
{{!-- only display sale countdown if product has custom field '__countdown_date' --}}
<div class="productView-saleCountdown" {{#unless (getVar '_salePercent' )}}style="display:none" {{/unless}}>
    <i class="icon" aria-hidden="true"><svg>
            <use href="#icon-badge-percent"></use>
        </svg></i>
    <div class="_content">
        {{#if theme_settings.product_sale_badges '===' 'percent'}}
        {{#replace '{percent}' (getVar '_saleCountdownLabel')}}
        {{getVar '_salePercent'}}%
        {{else}}
        <span class="_label">{{getVar '_saleCountdownLabel'}}</span>
        <span class="_salePercent">{{getVar '_salePercent'}}%</span>
        {{/replace}}
        {{else}}
        {{getVar '_saleCountdownLabel'}}
        {{/if}}
        <div class="_countdown" data-sale-countdown-date="{{getVar '_saleCountdownDate'}}"></div>
        <!-- Removed "data-sale-countdown-label="{{getVar '_saleCountdownEndLabel'}}"" from this line to eliminate unnecessary attribute-->
    </div>
</div>
{{/if}}

components/products/price-range:
{{#and price.price_range.min.with_tax price.price_range.max.with_tax}}
    <div class="price-section price-section--withTax price--withTax">
        <span class="price-label">{{theme_settings.pdp-price-label}}</span>
        <span class="price-now-label" style="display: none;">
            {{> components/products/price-label
                label_value=theme_settings.pdp-sale-price-label
                fallback=(lang "page_builder.pdp-sale-price-label")
            }}
        </span>
        <span data-product-price-with-tax class="price">{{price.price_range.min.with_tax.formatted}} - {{price.price_range.max.with_tax.formatted}}</span>
        {{#and price.price_range.min.without_tax price.price_range.max.without_tax}}
            <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.price_range.min.tax_label}}</abbr>
        {{/and}}
    </div>
    {{!-- Never display the "non-sales price" if there is a price range to be shown, but we do want the element on the page --}}
    <div class="price-section price-section--withTax non-sale-price--withTax" style="display: none;">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-non-sale-price-label
                fallback=(lang "page_builder.pdp-non-sale-price-label")
            }}
        </span>
        <span data-product-non-sale-price-with-tax class="price price--non-sale">
            {{price.non_sale_price_with_tax.formatted}}
        </span>
    </div>
{{/and}}
{{#and price.retail_price_range.min.with_tax price.retail_price_range.max.with_tax}}
    <div class="price-section price-section--withTax rrp-price--withTax">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-retail-price-label
                fallback=(lang "page_builder.pdp-retail-price-label")
            }}
        </span>
        <span data-product-rrp-price-with-tax class="price price--rrp">{{price.retail_price_range.min.with_tax.formatted}} - {{price.retail_price_range.max.with_tax.formatted}}</span>
    </div>
{{else}}
    {{#if price.with_tax}}
        <div class="price-section price-section--withTax rrp-price--withTax" style="display: none;">
            <span>
                {{> components/products/price-label
                    label_value=theme_settings.pdp-retail-price-label
                    fallback=(lang "page_builder.pdp-retail-price-label")
                }}
            </span>
            <span data-product-rrp-with-tax class="price price--rrp">
                {{price.rrp_with_tax.formatted}}
            </span>
        </div>
    {{/if}}
{{/and}}
{{#and price.price_range.min.without_tax price.price_range.max.without_tax}}
    <div class="price-section price-section--withoutTax price--withoutTax{{#and price_range.min.with_tax price_range.max.with_tax}} price-section--minor{{/and}}">
        <span class="price-label">{{theme_settings.pdp-price-label}}</span>
        <span class="price-now-label" style="display: none;">
            {{> components/products/price-label
                label_value=theme_settings.pdp-sale-price-label
                fallback=(lang "page_builder.pdp-sale-price-label")
            }}
        </span>
        <span data-product-price-without-tax class="price">{{price.price_range.min.without_tax.formatted}} - {{price.price_range.max.without_tax.formatted}}</span>
        {{#and price.price_range.min.with_tax price.price_range.max.with_tax}}
            <abbr title="{{lang 'products.excluding_tax'}}">{{lang 'products.price_without_tax' tax_label=price.price_range.min.tax_label}}</abbr>
        {{/and}}
    </div>
    {{!-- Never display the "non-sales price" if there is a price range to be shown, but we do want the element on the page --}}
    <div class="price-section price-section--withoutTax non-sale-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" style="display: none;">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-non-sale-price-label
                fallback=(lang "page_builder.pdp-non-sale-price-label")
            }}
        </span>
        <span data-product-non-sale-price-without-tax class="price price--non-sale">
            {{price.non_sale_price_without_tax.formatted}}
        </span>
    </div>
{{/and}}
{{#and price.retail_price_range.min.without_tax price.retail_price_range.max.without_tax}}
    <div class="price-section price-section--withoutTax rrp-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}">
        <span>
            {{> components/products/price-label
                label_value=theme_settings.pdp-retail-price-label
                fallback=(lang "page_builder.pdp-retail-price-label")
            }}
        </span>
        <span data-product-rrp-price-without-tax class="price price--rrp">{{price.retail_price_range.min.without_tax.formatted}} - {{price.retail_price_range.max.without_tax.formatted}}</span>
    </div>
{{else}}
    {{#if price.without_tax}}
        <div class="price-section price-section--withoutTax rrp-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" style="display: none;">
            <span>
                {{> components/products/price-label
                    label_value=theme_settings.pdp-retail-price-label
                    fallback=(lang "page_builder.pdp-retail-price-label")
                }}
            </span>
            <span data-product-rrp-price-without-tax class="price price--rrp">
                {{price.rrp_without_tax.formatted}}
            </span>
        </div>
    {{/if}}
{{/and}}
{{!-- Never display the "saving price" element by default if there is a price range on the page to be shown --}}
{{#if page_type '===' 'product'}}
     <div class="price-section price-section--saving price" style="display: none;">
            <span class="price">{{lang 'products.you_save_opening_text'}}</span>
            <span data-product-price-saved class="price price--saving">
                {{price.saved.formatted}}
            </span>
            <span class="price">{{lang 'products.you_save_closing_bracket'}}</span>
     </div>
{{/if}}

components/papathemes/sale-countdown/cus:
{{!--
    Input:
    - reset: boolean - reset `_saleCountdownDate`, `_saleCountdownLabel`, `_saleCountdownEndLabel`, `_salePercent`
    - name: string - custom field name.
        if custom field name is `__countdown_date`, it will set `_saleCountdownDate` value.
        if custom field name is `__countdown_label`, it will set `_saleCountdownLabel` and `_saleCountdownEndLabel` value.
    - value: string - custom field value
    - product: object
        set `_salePercent` value based on the product price rrp price or non sale price.
--}}

{{#if reset}}
    {{assignVar '_saleCountdownDate' 0}}
    {{assignVar '_saleCountdownLabel' (get 'string' (lang 'sale_countdown.sale'))}}
    {{assignVar '_saleCountdownEndLabel' 0}}

    {{#if product.price.rrp_without_tax}}
        {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.without_tax.value product.price.rrp_without_tax.value)) 100))}}
    {{else if product.price.rrp_with_tax}}
        {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.with_tax.value product.price.rrp_with_tax.value)) 100))}}
    {{else if product.price.non_sale_price_without_tax}}
        {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.without_tax.value product.price.non_sale_price_without_tax.value)) 100))}}
    {{else if product.price.non_sale_price_without_tax}}
        {{assignVar '_salePercent' (round (multiply (subtract 1 (divide product.price.with_tax.value product.price.non_sale_price_with_tax.value)) 100))}}
    {{else}}
        {{assignVar '_salePercent' 0}}
    {{/if}}
{{else}}
    {{#if name '===' '__countdown_date'}}
        {{assignVar '_saleCountdownDate' value}}
    {{else if name '===' '__countdown_label'}}
        {{assignVar '_saleCountdownLabel' (get 'string' (first (split value '|')))}}
        {{assignVar '_saleCountdownEndLabel' (get 'string' (last (split value '|')))}}
    {{/if}}
{{/if}}

components/papathemes/shipping-countdown:
{{!--
Input:
- reset: boolean - reset the variable `shippingCountdown`
- name: string - Custom field className
- value: string - Custom field value
--}}

{{#if reset}}
    {{assignVar 'shippingCountdown' 0}}
{{else}}
    {{#if name '===' '__shipping_countdown'}}
        {{assignVar 'shippingCountdown' value}}
    {{/if}}
{{/if}}

components/products/reviews:
{{#if settings.show_product_reviews}}
    <section class="productReviews" id="product-reviews" data-product-reviews>
        <p class="productView-collapsible-title">
            <button class="button button--plain _animation-on {{#unless theme_settings.collapse_reviews}}is-open{{/unless}}" data-collapsible="productReviews-content" type="button" aria-expanded="{{#if theme_settings.collapse_reviews}}false{{else}}true{{/if}}" aria-controls="productReviews-content">
                <span>{{lang 'products.reviews.customer_reviews'}}</span>
                <i class="icon" aria-hidden="true"><svg><use href="#icon-chevron-down-light"></use></svg></i>
            </button>
        </p>
        <div class="productView-collapsible-content _reviews {{#unless theme_settings.collapse_reviews}}is-open{{/unless}}" id="productReviews-content" aria-hidden="{{#if theme_settings.collapse_reviews}}true{{else}}false{{/if}}">
            <div class="productReview-averageRating">
                {{> components/products/ratings rating=product.rating}}
                <span>{{#if product.rating}}{{product.rating}}{{/if}}</span>
                <span>{{{lang 'products.reviews.link_to_review' total=product.num_reviews}}}</span>
            </div>

            <a href="{{product.url}}{{#if is_ajax}}#write_review{{/if}}"
                class="button button--outline productView-reviewLink"
                {{#unless is_ajax}}data-reveal-id="modal-review-form"{{/unless}}
                role="button"
            >
                {{lang 'products.reviews.new'}}
            </a>

            {{#if product.reviews.list}}
                <ul class="productReviews-list">
                    {{#each product.reviews.list}}
                        <li class="productReview">
                            <article>
                                <header>
                                    <span class="productReview-rating rating--small">
                                        {{> components/products/ratings rating=rating}}
                                        <span class="productReview-ratingNumber">{{ rating }}</span>
                                    </span>
                                    <p class="productReview-title">{{{ sanitize title }}}</p>
                                </header>
                                <p class="productReview-body">{{{ sanitize text }}}</p>
                                {{#if name}}
                                    <p class="productReview-author">
                                        {{{lang 'products.reviews.post_on_by' date=date name=(sanitize name) }}}
                                    </p>
                                {{else}}
                                    <p class="productReview-author">
                                        {{lang 'products.reviews.post_on_by' date=date name=(lang 'products.reviews.anonymous_poster')}}
                                    </p>
                                {{/if}}
                            </article>
                        </li>
                    {{/each}}
                </ul>
                {{> components/common/paginator pagination.reviews reload=true}}
            {{/if}}
        </div>
    </section>
{{/if}}

{{#if settings.show_product_reviews}}
    {{#unless is_ajax}}
        {{> components/products/modals/writeReview}}
    {{/unless}}
{{/if}}

components/products/options/set-rectangl:
{{#if (getVar (get 'string' (concat '__stepper_' (dashcase this.display_name))))}}
    {{assignVar 'isStepper' 1}}

    {{!-- always disable stepper for modifiers in modal --}}
    {{#if (getVar 'enableModifiersModal')}}
        {{#if state '===' 'modifier'}}
            {{assignVar 'isStepper' 0}}
        {{/if}}
    {{/if}}
{{else}}
    {{assignVar 'isStepper' 0}}
{{/if}}
<div class="form-field {{#if (getVar 'isStepper')}}form-field--stepper{{/if}}"
    {{#if (getVar 'isStepper')}} data-product-option-stepper {{/if}}
    data-product-attribute="set-rectangle" role="radiogroup" aria-labelledby="rectangle-group-label" data-product-attribute-state="{{state}}" data-product-attribute-id="{{id}}">

    {{#if (getVar 'isStepper')}}
        <button class="button button--checkbox _query-stepper-first" type="button" data-action="check">
            <span class="is-srOnly">{{lang 'common.change'}}</span>
        </button>
    {{/if}}

    <label class="form-label form-label--alternate form-label--inlineSmall" id="rectangle-group-label">
        {{this.display_name}}:
        <span data-option-value></span>

        {{> components/common/requireness-msg}}
    </label>

    {{#unless required}}
        <input
            class="form-radio"
            type="radio"
            id="attribute_rectangle__{{id}}_none"
            name="attribute[{{id}}]"
            value=""
            checked="{{#if defaultValue '==' ''}}checked{{/if}}"
        >
        <label class="form-option" for="attribute_rectangle__{{id}}_none">
            <span class="form-option-variant">{{lang 'products.none'}}</span>
        </label>
    {{/unless}}

    {{#each this.values}}
    <div class="form-option-wrapper">
        <input
            class="form-radio"
            type="radio"
            id="attribute_rectangle__{{../id}}_{{id}}"
            name="attribute[{{../id}}]"
            value="{{id}}"
            {{#if selected}}
                checked
                data-default
            {{/if}}
            {{#if ../required}}required{{/if}}
        >
        <label class="form-option" for="attribute_rectangle__{{../id}}_{{id}}" data-product-attribute-value="{{id}}">
            <span class="form-option-variant">{{this.label}}</span>
        </label>
    </div>
    {{/each}}

    {{#if (getVar 'isStepper')}}
        <button class="button button--outline _stepper _query-stepper-last" type="button" data-action="dec">
            <span class="icon" aria-hidden="true"><svg><use href="#icon-minus"></use></svg></span>
            <span class="is-srOnly">{{lang 'common.previous'}}</span>
        </button>
        <button class="button button--outline _stepper _query-stepper-last" type="button" data-action="inc">
            <span class="icon" aria-hidden="true"><svg><use href="#icon-plus"></use></svg></span>
            <span class="is-srOnly">{{lang 'common.next'}}</span>
        </button>
    {{/if}}
</div>
